-- Migración: catálogo de composición de alimentos (Ecuador 2021)
-- Fuente: Tabla de Composición de Alimentos para Ecuador 2021 (valores por 100 g;
-- la categoría "Alimentos expresados en 100 ml" es por 100 ml).
-- Pegar COMPLETO en el SQL Editor de Supabase (proyecto swgqlrbztvqikkyitqtx) y Run.

create table if not exists public.food_nutrition (
  id bigint generated always as identity primary key,
  categoria text not null,
  alimento text not null,
  nombre_ingles text,
  kcal numeric,
  proteina_g numeric,
  grasa_g numeric,
  grasa_saturada_g numeric,
  carbohidratos_g numeric,
  fibra_g numeric,
  colesterol_mg numeric,
  sodio_mg numeric,
  potasio_mg numeric,
  calcio_mg numeric,
  hierro_mg numeric,
  zinc_mg numeric,
  vitamina_c_mg numeric,
  folatos_ug numeric
);

comment on table public.food_nutrition is 'Tabla de composición de alimentos Ecuador 2021, por 100 g (o 100 ml según categoría)';

alter table public.food_nutrition enable row level security;

-- Datos de referencia públicos: cualquiera puede leer, nadie escribe por API
-- (solo dashboard/service_role).
drop policy if exists "food_nutrition lectura publica" on public.food_nutrition;
create policy "food_nutrition lectura publica"
  on public.food_nutrition for select using (true);

create index if not exists food_nutrition_categoria_idx on public.food_nutrition (categoria);
create index if not exists food_nutrition_alimento_idx on public.food_nutrition using gin (to_tsvector('spanish', alimento));











